package thaumcraft.data;

import java.util.*;
import net.minecraft.nbt.*;

/** Definitions accompany the authoritative knowledge snapshot, including after /reload. */
public final class AspectDataSync {
    public record Definitions(Map<String,Map<String,Integer>> objects,Map<String,Map<String,Integer>> entities,Map<String,List<ThaumcraftData.EntityVariant>> variants,Map<String,String> scanGroups,StackAspectRules.Settings modifiers){public static final Definitions EMPTY=new Definitions(Map.of(),Map.of(),Map.of(),Map.of(),StackAspectRules.Settings.EMPTY);}
    public static void encode(CompoundTag target,ThaumcraftData.Snapshot snapshot){target.put("objectAspectDefinitions",maps(snapshot.objects()));target.put("entityAspectDefinitions",maps(snapshot.entities()));var groups=new CompoundTag();snapshot.scanGroups().forEach(groups::putString);target.put("scanGroups",groups);var variants=new CompoundTag();snapshot.entityVariants().forEach((key,entries)->{var list=new ListTag();for(var entry:entries){var tag=new CompoundTag();tag.putString("field",entry.field());tag.putString("value",entry.value());tag.put("aspects",quantities(entry.aspects()));list.add(tag);}variants.put(key,list);});target.put("entityAspectVariants",variants);target.put("stackAspectMinimums",maps(snapshot.modifiers().items()));target.put("potionAspectBases",maps(snapshot.modifiers().potionBases()));target.put("potionAspectEffects",maps(snapshot.modifiers().effects()));target.put("enchantmentAspectMinimums",maps(snapshot.modifiers().enchantments()));}
    public static Definitions decode(CompoundTag source){var groups=new LinkedHashMap<String,String>();var encodedGroups=source.getCompound("scanGroups");for(var key:encodedGroups.getAllKeys())groups.put(key,encodedGroups.getString(key));var variants=new LinkedHashMap<String,List<ThaumcraftData.EntityVariant>>();var encoded=source.getCompound("entityAspectVariants");for(var key:encoded.getAllKeys()){var entries=new ArrayList<ThaumcraftData.EntityVariant>();for(var value:encoded.getList(key,Tag.TAG_COMPOUND)){var tag=(CompoundTag)value;entries.add(new ThaumcraftData.EntityVariant(tag.getString("field"),tag.getString("value"),readQuantities(tag.getCompound("aspects"))));}variants.put(key,List.copyOf(entries));}return new Definitions(readMaps(source.getCompound("objectAspectDefinitions")),readMaps(source.getCompound("entityAspectDefinitions")),Map.copyOf(variants),Map.copyOf(groups),new StackAspectRules.Settings(readMaps(source.getCompound("stackAspectMinimums")),readMaps(source.getCompound("potionAspectBases")),readMaps(source.getCompound("potionAspectEffects")),readMaps(source.getCompound("enchantmentAspectMinimums"))));}
    private static CompoundTag maps(Map<String,Map<String,Integer>> values){var tag=new CompoundTag();values.forEach((key,amounts)->tag.put(key,quantities(amounts)));return tag;}
    private static CompoundTag quantities(Map<String,Integer> values){var tag=new CompoundTag();values.forEach(tag::putInt);return tag;}
    private static Map<String,Map<String,Integer>> readMaps(CompoundTag tag){var result=new LinkedHashMap<String,Map<String,Integer>>();for(var key:tag.getAllKeys())result.put(key,readQuantities(tag.getCompound(key)));return Map.copyOf(result);}
    private static Map<String,Integer> readQuantities(CompoundTag tag){var result=new LinkedHashMap<String,Integer>();for(var key:tag.getAllKeys())if(tag.getInt(key)>0)result.put(key,Math.min(64,tag.getInt(key)));return Map.copyOf(result);}
    private AspectDataSync(){}
}
